fn drop_key(order: List[Str], k: Str) -> List[Str] {
  return order.filter(fn(x) => x != k)
}

pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  var vals: Map[Str, Str] = Map {}
  var order: List[Str] = []
  var out: List[Str] = []
  for op in ops {
    let parts = op.split(" ")
    let key = parts.get_or(1, "")
    if parts.get_or(0, "") == "put" {
      if capacity > 0 {
        let value = parts.drop(2).join(" ")
        if vals.has(key) {
          order = drop_key(order, key)
        } else if vals.len() >= capacity {
          let old = order.first().unwrap_or("")
          vals = vals.remove(old)
          order = order.drop(1)
        }
        order = order.push(key)
        vals = vals.set(key, value)
      }
    } else {
      out = out.push(vals.get(key).unwrap_or("-"))
      if vals.has(key) {
        order = drop_key(order, key)
        order = order.push(key)
      }
    }
  }
  return out
}
